import sys; sys.path.insert(0, __import__("os").path.join(__import__("os").path.dirname(__file__), "..", "..", "pipeline"))
from scriptkit import sc, ch, save, S

# Grandma Ruth's Story · Chapter 1 (novela, Season 1) · Billionaires Histories, new format
# The Telegram Came the Week I Was Born (1944) | Grandma Ruth, Chapter 1
# Hook to chapter 2: the neighbor counts the months on her fingers and looks at Dorothy's belly.

sc("""Emma, put the phone down. Jack, you too. Come here, both of you. You've been asking me for years to tell you the whole story. Not the nice parts. The whole thing. Where I come from, and why your great-grandmother never spoke to her brother-in-law again. Well, I'm eighty-two now. And if I don't tell it, nobody will. So we're going to start at the very beginning. The week I was born.""",
   "1940s grandmother old family photographs", "THE WHOLE STORY")
sc("""It will take me a long time, sweethearts. A whole year of nights, maybe. There are things in this story I have never told your mother. There are things I didn't know myself until I was a grown woman with children of my own. But I promise you this. Every night, I'll tell you one piece. And every piece is true.""",
   "1940s old letters photographs box", "EVERY PIECE IS TRUE")

ch("Mansfield, 1944")
sc("""It was August of nineteen forty-four, in Mansfield, Ohio. The war had been going on for almost three years. Every house on Maple Street had a little flag in the front window, white with a red border and a blue star in the middle. A blue star meant somebody from that house was fighting. A gold star meant they weren't coming home.""",
   "1940s service flag blue star window", "A BLUE STAR")
sc("""Our house had one blue star. It was for my father, Walter Miller. He was twenty-six years old, a private in the infantry, and he had shipped out the October before. Nobody knew exactly where he was. The letters came with black lines through half of the words, so the enemy wouldn't learn anything. My mother read them anyway, over and over, until the paper was soft.""",
   "1940s soldier letter censored V-mail", "WALTER MILLER")
sc("""My mother was Dorothy. She was twenty-three that summer, and she was the prettiest girl on Maple Street. Everybody said so. She had dark hair she pinned up in rolls, and she sang when she cooked. She had wanted to be a teacher. Then the war came, and Walter asked her to marry him three weeks before he left, and she said yes.""",
   "1940s young woman portrait housewife", "DOROTHY")
sc("""She lived with Grandma Pearl while Walter was gone. That was Walter's mother, born in eighteen ninety-five. A tough old bird who had buried a husband and raised two boys through the Depression on a seamstress's wages. Pearl didn't trust banks, didn't trust doctors, and didn't trust anybody who smiled too much. That last part will matter later.""",
   "1940s elderly woman portrait stern", "GRANDMA PEARL")

sc("""They were married at the courthouse on a Friday afternoon in September of forty-three. No church, no white dress. There wasn't time, and there wasn't money. Mother wore a blue suit she borrowed from her sister, and she carried three roses from Grandma Pearl's garden. There's one photograph of that day. Walter is in his uniform, smiling. And standing right beside him, as his best man, is his brother Frank. Remember that photograph. We'll come back to it.""",
   "1940s wartime wedding couple soldier courthouse", "SEPTEMBER, 1943")
sc("""Walter had three weeks of leave before he shipped out. They spent them in the little back bedroom at Pearl's house, because there was nowhere else to go. Then on the second of October, Mother and Pearl and Frank took him to the train station downtown. The platform was full of boys in uniform and girls in tears. Walter kissed my mother goodbye, and then he put his hand on Frank's shoulder and said, take care of her for me. Frank said he would.""",
   "1940s soldiers train station goodbye", "TAKE CARE OF HER")

ch("The home front")
sc("""You have to understand what that summer was like. Everything was rationed. Sugar, coffee, butter, meat, gasoline, shoes. You got a little book of stamps, and when the stamps were gone, you went without. Mother saved bacon grease in a can by the stove and took it to the butcher, because they used the fat to make explosives. Every woman on the street did.""",
   "1940s ration book stamps home front", "RATIONED")
sc("""The factories in Mansfield ran day and night for the war. The Westinghouse plant, the steel mill, Ohio Brass. Women worked on the lines in coveralls with their hair tied up in scarves. My mother couldn't, not that summer. She was eight months along with me, big as a house, she said, and hot as a stove.""",
   "1940s women factory workers war production", "DAY AND NIGHT")
sc("""And there was one man on Maple Street who wasn't at the war. My father's younger brother. Frank. Uncle Frank was twenty-four, tall and handsome, with a laugh you could hear from two houses down. The Army had turned him away because of something with his heart. He worked at the steel mill and came by our house almost every evening to check on Dorothy, he said. To see if she needed anything.""",
   "1940s handsome young man portrait fedora", "UNCLE FRANK")
sc("""Frank and Walter had always been like that, Pearl said. Walter was the older one, the serious one, the one who got the good grades and the steady job and the pretty girl. Frank was the fun one. And Frank had always, always wanted whatever Walter had. When they were boys, if Walter got a new pair of shoes, Frank would cry until he got the same ones. Pearl thought he'd grown out of it. She was wrong.""",
   "1930s two brothers boys old photograph", "WHATEVER WALTER HAD")

sc("""Grandma Pearl watched him every time he came through that door. She never said anything. She just watched. I didn't understand that look until I was forty years old. But I'm getting ahead of myself.""",
   "1940s kitchen door screen evening", "SHE JUST WATCHED")

ch("The telegram")
sc("""On Monday, the seventh of August, the Western Union boy rode his bicycle up Maple Street. Sweethearts, you don't know what that meant. In those days, every mother and every wife in America was afraid of that boy. Because the telegrams from the War Department came on a bicycle. And every woman on the street came out onto her porch to see which house he would stop at.""",
   "1940s Western Union telegram messenger bicycle", "THE BICYCLE")
sc("""He stopped at ours. Mrs. Pruitt next door told me later that my mother was hanging laundry in the back, and she came around the side of the house with a clothespin still in her mouth. The boy was only fifteen. He held out the yellow envelope, and he couldn't look at her.""",
   "1940s woman hanging laundry backyard", "A CLOTHESPIN IN HER MOUTH")
sc("""The telegram said, The Secretary of War desires me to express his deep regret that your husband, Private Walter J. Miller, has been reported missing in action since the twenty-fifth of July in France. That was all. Missing. Not dead. Not alive. Missing. In those days a word like that could last for months.""",
   "1940s War Department telegram missing in action", "MISSING IN ACTION")
sc("""My mother didn't cry, Grandma Pearl said. She folded the telegram in half, and put it in her apron pocket, and went back and finished hanging the laundry. Every sheet. Then she went inside and sat down at the kitchen table. And that's when her water broke.""",
   "1940s kitchen table woman alone", "AND THEN HER WATER BROKE")

ch("The night I was born")
sc("""There was no car. Grandma Pearl didn't drive, and the gasoline was rationed anyway. So Pearl ran next door to the Pruitts, and Mrs. Pruitt ran to the corner to use the telephone at the drugstore, and the only person who answered was Frank. He came in his truck from the mill, still black with soot, and he carried my mother to it in his arms.""",
   "1940s pickup truck night street", "FRANK CAME")
sc("""I was born at Mansfield General Hospital at four in the morning on August the eighth, nineteen forty-four. Seven pounds, two ounces. Dark hair like my mother. The nurse wrote my name down as Ruth Ann Miller. Ruth after nobody in particular. My mother just liked it. She said it meant a friend.""",
   "1940s hospital nursery newborn babies", "RUTH ANN MILLER")
sc("""Fathers weren't allowed in the delivery room back then, even if they were home. They waited in a little room down the hall, smoking. But my father was in France, missing. So the man waiting in that little room, all night long, pacing up and down, was Frank.""",
   "1940s hospital waiting room", "PACING ALL NIGHT")
sc("""The nurse came out and told him, it's a girl, Mister Miller. And Frank didn't correct her. Mrs. Pruitt was there. She heard it. She never forgot it either.""",
   "1940s nurse hospital corridor", "IT'S A GIRL, MISTER MILLER")

ch("The first week")
sc("""We came home on the fourteenth. In those days they kept you in the hospital for a week. Mother carried me up the porch steps, and Grandma Pearl had put a little white crib in the front room, right under the window with the blue star. And every day that week, Mother sat in the rocking chair and looked at that star, and then looked at me.""",
   "1940s mother rocking chair baby", "UNDER THE BLUE STAR")
sc("""The neighbors came, the way neighbors did. They brought casseroles and baby blankets and prayers. The ladies from the Lutheran church came on Wednesday. Each one held me, and said how sweet, and then lowered her voice and asked Dorothy if there was any news from France. There wasn't. Not that week. Not for a long time.""",
   "1940s women visiting neighbors casserole", "ANY NEWS?")
sc("""Frank came every evening. He brought a rattle he had carved himself out of a piece of maple. He brought oranges, which you could hardly get. He sat on the porch with my mother until dark. They talked quietly, so Pearl couldn't hear. And Pearl sat in the kitchen with the light off, listening anyway.""",
   "1940s couple porch evening talking", "UNTIL DARK")

ch("Mrs. Pruitt")
sc("""On Saturday, the nineteenth of August, the news came on the radio that Paris was about to be free. Everybody on Maple Street came out into the street. People hugged. Mr. Pruitt rang the dinner bell. And my mother stood on the porch holding me, and she cried for the first time since the telegram. Because Walter was somewhere in France. And she didn't know if he would ever hear the bells.""",
   "1944 liberation Paris celebration crowd", "PARIS")
sc("""That evening Mrs. Pruitt came over with a pie. Peach. She was a big woman with small eyes who knew everything that happened on our street, sometimes before it happened. She sat down in the front room and held me on her knee, and she looked at me for a long time. Too long. My mother noticed.""",
   "1940s older woman neighbor portrait", "MRS. PRUITT")
sc("""And then Mrs. Pruitt said, very sweetly, she's a big healthy baby for being so early, Dorothy. My mother said, she wasn't early. And Mrs. Pruitt smiled, and said, no, of course not, dear. Walter left in October, didn't he?""",
   "1940s living room two women talking", "WALTER LEFT IN OCTOBER")
sc("""Grandma Pearl was standing in the kitchen doorway. She told me this herself, forty years later, the week before she died. She said Mrs. Pruitt handed the baby back to my mother. And then, under the table, where she thought nobody could see, she began to count the months on her fingers. October. November. December. January.""",
   "1940s woman hands counting fingers table", "OCTOBER. NOVEMBER.")
sc("""Mrs. Pruitt stopped counting. She looked at my mother's face, and then she looked down at my mother's belly, still round from carrying me. And she didn't say another word. She didn't have to.""",
   "1940s pregnant woman silhouette window", "SHE DIDN'T HAVE TO")

ch("Next time")
sc("""That's enough for tonight, sweethearts. No, Jack, I'm not telling you what she was counting. You'll figure it out. You're smart. And Emma, don't you look at me like that. You'll hear it all, I promise, the way I heard it, a piece at a time.""",
   "1940s old family photo album", "THAT'S ENOUGH FOR TONIGHT")
sc("""Tomorrow I'll tell you about the letter my mother hid in the flour tin. And the name it was signed with. Goodnight, sweethearts. And if you want to hear the next chapter, you know where to find your grandma. Every night. Right here.""",
   "1940s house at night porch light", "CHAPTER 2: THE FLOUR TIN")

for s in S:  # documentary look: four photos per scene and the six rotating camera moves
    s["cuts"], s["moves"] = 4, True

